import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import { VLC_INSTALLER_URL, withBaseUrl } from '../vlc'

/**
 * public/downloads/install-m3uhub-vlc.cmd embeds protocol/handler.ps1 as
 * base64. It is generated by scripts/build-installer.mjs (wired into
 * prebuild/pretest), but this test is the hard guarantee: if anyone edits
 * handler.ps1 without regenerating the installer, this fails the build.
 */

const here = path.dirname(fileURLToPath(import.meta.url))
const root = path.resolve(here, '..', '..', '..')
const HANDLER_PATH = path.join(root, 'protocol', 'handler.ps1')
const INSTALLER_PATH = path.join(root, 'public', 'downloads', 'install-m3uhub-vlc.cmd')

function hasBom(bytes: Buffer): boolean {
  return bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf
}

function extractBase64Payload(cmdText: string): string {
  // Payload lines look like: echo <base64-chunk>>>"%PAYLOAD%"
  const lines: string[] = []
  for (const line of cmdText.split(/\r?\n/)) {
    const match = /^echo ([A-Za-z0-9+/=]+)>>"%PAYLOAD%"$/.exec(line.trim())
    if (match) lines.push(match[1])
  }
  return lines.join('')
}

describe('install-m3uhub-vlc.cmd — embedded handler payload', () => {
  it('decodes to byte-identical handler.ps1, BOM included', () => {
    const handlerBytes = readFileSync(HANDLER_PATH)
    const cmdText = readFileSync(INSTALLER_PATH, 'utf8')

    expect(hasBom(handlerBytes)).toBe(true)

    const base64 = extractBase64Payload(cmdText)
    expect(base64.length).toBeGreaterThan(0)

    const decoded = Buffer.from(base64, 'base64')
    expect(hasBom(decoded)).toBe(true)
    expect(decoded.equals(handlerBytes)).toBe(true)
  })

  it('stays well under a sane size budget for a downloadable one-file installer', () => {
    const sizeBytes = readFileSync(INSTALLER_PATH).length
    expect(sizeBytes).toBeLessThan(40 * 1024)
  })

  it('does not reference the developer machine clone path', () => {
    const cmdText = readFileSync(INSTALLER_PATH, 'utf8')
    const driveClonePath = ['D', ':', 'project'].join('\\')
    expect(cmdText.toLowerCase()).not.toContain(driveClonePath.toLowerCase())
  })
})

/**
 * The installer link must survive a GitHub Pages project deploy, where the app
 * is served from /m3u-hub/ instead of the domain root. Vite exposes that prefix
 * as import.meta.env.BASE_URL ('/' in dev, '/m3u-hub/' in the Pages build).
 */
describe('installer download URL — base path handling', () => {
  const FILE = 'downloads/install-m3uhub-vlc.cmd'

  it('uses BASE_URL, and BASE_URL is "/" under vitest/dev', () => {
    expect(import.meta.env.BASE_URL).toBe('/')
    expect(VLC_INSTALLER_URL).toBe(`/${FILE}`)
  })

  it('resolves under the GitHub Pages subpath with no double slash', () => {
    expect(withBaseUrl(FILE, '/m3u-hub/')).toBe(`/m3u-hub/${FILE}`)
    // Tolerate a base without the trailing slash, and a path with a leading one.
    expect(withBaseUrl(FILE, '/m3u-hub')).toBe(`/m3u-hub/${FILE}`)
    expect(withBaseUrl(`/${FILE}`, '/m3u-hub/')).toBe(`/m3u-hub/${FILE}`)
    expect(withBaseUrl(FILE, '/')).toBe(`/${FILE}`)
    expect(withBaseUrl(FILE, '')).toBe(`/${FILE}`)
    for (const base of ['/', '/m3u-hub/', '/m3u-hub']) {
      expect(withBaseUrl(FILE, base)).not.toContain('//')
    }
  })

  it('points at a file that actually exists in public/', () => {
    const url = withBaseUrl(FILE, '/m3u-hub/')
    const relative = url.slice('/m3u-hub/'.length)
    expect(readFileSync(path.join(root, 'public', relative)).length).toBeGreaterThan(0)
  })
})
